import yaml
with open('registry.yaml') as f:
    data = yaml.safe_load(f)

suites = ['goal', 'object', 'spatial', 'long']
modes = ['vla-only', 'crm-k2', 'adaptive']
seeds = ['42', '43', '44']

pi05_exps = {k:v for k,v in data.get('experiments',{}).items() if 'pi05' in k.lower() or ('eval-pi05' in k.lower())}

for suite in suites:
    for mode in modes:
        for seed in seeds:
            matches = []
            for eid, exp in pi05_exps.items():
                el = eid.lower()
                if suite not in el: continue
                if f's{seed}' not in el and f'seed{seed}' not in el: continue

                is_mode = False
                if mode == 'vla-only' and ('vla-only' in el or 'vla_only' in el):
                    is_mode = True
                elif mode == 'crm-k2' and ('crm-k2' in el or 'crm_k2' in el):
                    is_mode = True
                elif mode == 'adaptive' and 'adaptive' in el and 'crm-k2' not in el and 'crm_k2' not in el:
                    is_mode = True
                if not is_mode: continue
                matches.append((eid, exp.get('status'), exp.get('conclusion','-')))

            # Priority: RUNNING > DONE(success) > ANALYZING > others
            best = None
            for m in matches:
                if m[1] == 'RUNNING':
                    best = m; break
            if not best:
                for m in matches:
                    if m[1] == 'DONE' and m[2] == 'success':
                        best = m; break
            if not best:
                for m in matches:
                    if m[1] == 'ANALYZING':
                        best = m; break
            if not best and matches:
                best = matches[0]

            status = f'{best[1]}({best[2]})' if best else '❌ MISSING'
            eid_s = best[0][:50] if best else ''
            symbol = '✅' if best and best[1]=='DONE' and best[2]=='success' else '🔄' if best and best[1]=='RUNNING' else '🔍' if best and best[1]=='ANALYZING' else '❌'
            print(f'{symbol} {suite:8} {mode:10} s{seed}: {status:22} {eid_s}')
    print()
"

